-- 4. Update all 1302 GPUs via verified 63-chipset TechPowerUp anchors (+ AIB factory boost OC delta)
WITH gpu_anchors(ord, kw, base_rel, ts_g, sn, ref_boost, need16) AS (VALUES
  (1,'rtx 4070 ti super',69.0,24800,6250,2610,FALSE),
  (2,'rtx 4000 sff ada',36.0,12800,3100,1565,FALSE),
  (3,'radeon pro w7900',72.0,27200,6800,2495,FALSE),
  (4,'rtx 5060 ti',48.0,16900,4150,2572,TRUE),
  (5,'rtx 4080 super',79.0,28800,7450,2550,FALSE),
  (6,'rtx 4070 super',60.0,21200,5250,2475,FALSE),
  (7,'rtx 4070 gddr6',51.0,17800,4350,2475,FALSE),
  (8,'rtx 4060 ti',42.0,13800,3300,2535,TRUE),
  (9,'rtx 5090 d v2',122.0,44500,13200,2407,FALSE),
  (10,'rx 9060 xt',47.0,16800,4150,3130,TRUE),
