  (14,'rtx 4000 ada',46.0,16400,4000,2175,FALSE),
  (15,'rtx 5070 ti',75.0,27800,7150,2452,FALSE),
  (16,'rtx 5060 ti',47.0,16600,4050,2572,FALSE),
  (17,'rtx 4070 ti',63.0,22800,5650,2610,FALSE),
  (18,'rtx 4060 ti',41.0,13600,3250,2535,FALSE),
  (19,'rtx 3090 ti',67.0,22400,5500,1860,FALSE),
  (20,'rtx 3080 ti',60.0,19800,4800,1665,FALSE),
  (21,'rtx 3070 ti',46.0,15100,3600,1770,FALSE),
  (22,'rtx 3060 ti',38.0,12100,2850,1665,FALSE),
  (23,'rx 9070 gre',58.0,21400,5350,2750,FALSE),
  (24,'rx 7900 xtx',80.0,29800,7350,2500,FALSE),
  (25,'rx 7900 gre',59.0,22400,5300,2245,FALSE),
  (26,'rtx 5090 d',131.0,47800,14100,2407,FALSE),
  (27,'rtx 4090 d',92.0,33800,8900,2520,FALSE),
  (28,'rx 9070 xt',75.0,28600,7250,2970,FALSE),
  (29,'rx 9060 xt',45.0,16200,4000,3130,FALSE),
  (30,'rx 7900 xt',68.0,25600,6150,2400,FALSE),
  (31,'rx 7800 xt',54.0,19800,4650,2430,FALSE),
  (32,'rx 7700 xt',46.0,17100,3950,2544,FALSE),
  (33,'rx 7600 xt',35.0,11800,2650,2755,FALSE),
  (34,'rx 6950 xt',61.0,21800,5150,2310,FALSE),
  (35,'rx 6900 xt',57.0,20400,4750,2250,FALSE),
  (36,'rx 6800 xt',54.0,19200,4450,2250,FALSE),
  (37,'rx 6750 xt',42.0,13800,3200,2600,FALSE),
  (38,'rx 6700 xt',39.0,12800,2950,2581,FALSE),
  (39,'rx 6650 xt',33.0,10400,2350,2635,FALSE),
  (40,'rx 6600 xt',31.0,9800,2200,2589,FALSE),
  (41,'rtx 5090',133.0,48500,14400,2407,FALSE),
  (42,'rtx 5080',86.0,32600,8900,2617,FALSE),
  (43,'rtx 5070',60.0,22400,5600,2512,FALSE),
  (44,'rtx 5060',39.0,13800,3300,2497,FALSE),
  (45,'rtx 5050',28.0,9800,2300,2572,FALSE),
  (46,'rtx 4090',100.0,36800,9800,2520,FALSE),
  (47,'rtx 4080',77.0,28100,7250,2505,FALSE),
  (48,'rtx 4070',52.0,18200,4450,2475,FALSE),
  (49,'rtx 4060',34.0,10800,2550,2460,FALSE),
  (50,'rtx 4010',11.0,3400,800,2000,FALSE),
  (51,'rtx 3090',61.0,20300,4950,1695,FALSE),
  (52,'rtx 3080',53.0,17800,4300,1710,FALSE),
  (53,'rtx 3070',43.0,13800,3300,1725,FALSE),
  (54,'rtx 3060',29.0,8900,2050,1777,FALSE),
  (55,'rtx 3050',20.0,6200,1400,1777,FALSE),
  (56,'arc b580',38.0,14600,3400,2670,FALSE),
  (57,'arc b570',33.0,12600,2900,2500,FALSE),
  (58,'arc a770',32.0,13500,2900,2400,FALSE),
  (59,'arc a750',29.0,12300,2650,2400,FALSE),
  (60,'rx 9070',66.0,24800,6200,2520,FALSE),
  (61,'rx 9060',37.0,13100,3150,2900,FALSE),
  (62,'rx 7700',42.0,15400,3550,2400,FALSE),
  (63,'rx 7600',33.0,10900,2450,2655,FALSE),
  (64,'rx 6800',47.0,16300,3800,2105,FALSE),
  (65,'rx 6600',26.0,8200,1850,2491,FALSE)
), matched_gpu AS (
  SELECT DISTINCT ON (hc.id)
    hc.id,
    GREATEST(COALESCE((hc.spec_payload->>'vram_mb')::DOUBLE PRECISION / 1024.0, 8.0), 2.0) AS vram_gb,
    COALESCE((hc.spec_payload->>'boost_clock_mhz')::DOUBLE PRECISION, 0.0) AS boost_mhz,
    a.base_rel, a.ts_g, a.sn, a.ref_boost
  FROM public.hardware_catalog hc
  JOIN gpu_anchors a ON (
    (LOWER(COALESCE(hc.spec_payload->>'chipset','') || ' ' || hc.model) ~ ('(^|[^a-z0-9])' || a.kw || '([^a-z0-9]|$)'))
    AND (NOT a.need16 OR COALESCE((hc.spec_payload->>'vram_mb')::INT, 0) >= 15800)
  )
  WHERE hc.category = 'GPU' AND hc.is_active = TRUE
  ORDER BY hc.id, a.ord ASC
), computed_gpu AS (
  SELECT
    id, vram_gb,
    ROUND((base_rel * (1.0 + CASE WHEN boost_mhz > 800 AND ref_boost > 800 THEN LEAST(0.025, GREATEST(-0.015, ((boost_mhz - ref_boost) / ref_boost) * 0.35)) ELSE 0.0 END))::NUMERIC, 1)::DOUBLE PRECISION AS rel_idx,
    ROUND((ts_g * (1.0 + CASE WHEN boost_mhz > 800 AND ref_boost > 800 THEN LEAST(0.025, GREATEST(-0.015, ((boost_mhz - ref_boost) / ref_boost) * 0.35)) ELSE 0.0 END))::NUMERIC)::INT AS ts_adj,
    ROUND((sn * (1.0 + CASE WHEN boost_mhz > 800 AND ref_boost > 800 THEN LEAST(0.025, GREATEST(-0.015, ((boost_mhz - ref_boost) / ref_boost) * 0.35)) ELSE 0.0 END))::NUMERIC)::INT AS sn_adj
  FROM matched_gpu
)
UPDATE public.hardware_catalog AS hc SET
  benchmark_score = GREATEST(5, LEAST(100, ROUND(((cg.rel_idx / 133.0) * 100.0)::NUMERIC)::INT)),
  benchmark_gaming_index = GREATEST(5, ROUND(cg.rel_idx::NUMERIC)::INT),
  benchmark_tier = CASE WHEN cg.rel_idx >= 95 THEN 'S+-Tier' WHEN cg.rel_idx >= 72 THEN 'S-Tier' WHEN cg.rel_idx >= 54 THEN 'A+-Tier' WHEN cg.rel_idx >= 38 THEN 'A-Tier' WHEN cg.rel_idx >= 26 THEN 'B-Tier' ELSE 'C-Tier' END,
  benchmark_test_suite = 'TechPowerUp & ML Calibrated v6 (Ref: Ryzen 7 9800X3D)',
  gpu_synthetic = COALESCE(hc.gpu_synthetic, '{}'::jsonb) || jsonb_build_object('time_spy_graphics', cg.ts_adj, 'steel_nomad', cg.sn_adj),
  game_fps = pg_temp.sim_v6_matrix(cg.rel_idx, cg.vram_gb, 100.0, TRUE, 1, 8),
  catalog_revision = 8,
  updated_at = NOW()
FROM computed_gpu cg
WHERE hc.id = cg.id;

-- 5. Enrich missing image_url from exact same-brand & same-chipset/socket/gen sibling SKUs
UPDATE public.hardware_catalog hc SET image_url = sub.img, images = jsonb_build_array(sub.img), catalog_revision = 8, updated_at = NOW()
FROM (
  SELECT DISTINCT ON (h1.id) h1.id, h2.image_url AS img
  FROM public.hardware_catalog h1
  JOIN public.hardware_catalog h2 ON h2.category = h1.category AND LOWER(h2.brand) = LOWER(h1.brand)
    AND h2.image_url LIKE 'https://%'
    AND ((h1.category = 'GPU' AND LOWER(h1.spec_payload->>'chipset') = LOWER(h2.spec_payload->>'chipset'))
      OR (h1.category = 'MOTHERBOARD' AND LOWER(h1.spec_payload->>'chipset') = LOWER(h2.spec_payload->>'chipset') AND h1.spec_payload->>'form_factor' = h2.spec_payload->>'form_factor')
      OR (h1.category = 'RAM' AND h1.spec_payload->>'generation' = h2.spec_payload->>'generation' AND h1.spec_payload->>'module_count' = h2.spec_payload->>'module_count')
      OR (h1.category = 'CPU' AND LOWER(h1.spec_payload->>'socket') = LOWER(h2.spec_payload->>'socket')))
  WHERE h1.is_active = TRUE AND (h1.image_url IS NULL OR h1.image_url = '')
) sub WHERE hc.id = sub.id;

-- 6. Bump catalog_meta.latest_revision to 8 so mobile clients pull the calibrated delta
UPDATE public.catalog_meta SET latest_revision = 8, total_items = (SELECT COUNT(*) FROM public.hardware_catalog WHERE is_active = TRUE), last_delta_at = NOW(), last_checked_at = NOW() WHERE id = 1;
COMMIT;
